-- Reviewed senior batch 005; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":2558,"word":"exert","meaning":"施加","example":"The students had to exert steady pressure to move the heavy cart.","example_zh":"學生必須持續施力，才能推動沉重的推車。","original_meaning":"施加","original_example":"Exert pressure.","original_example_zh":"施加壓力。"},{"source_id":2559,"word":"expedition","meaning":"遠征；考察","example":"Our class joined an expedition to study plants in the mountain forest.","example_zh":"我們班參加考察隊，研究山林裡的植物。","original_meaning":"遠征","original_example":"A polar expedition.","original_example_zh":"極地探險。"},{"source_id":2560,"word":"fallacy","meaning":"謬誤","example":"The teacher exposed the fallacy that heavier objects always fall faster.","example_zh":"老師指出較重的物體總是落得較快這種謬誤。","original_meaning":"謬誤","original_example":"A logical fallacy.","original_example_zh":"邏輯謬誤。"},{"source_id":2561,"word":"famine","meaning":"饑荒","example":"Relief workers delivered grain to families affected by the famine.","example_zh":"救援人員把穀物送到受饑荒影響的家庭。","original_meaning":"饑荒","original_example":"A great famine.","original_example_zh":"一場大饑荒。"},{"source_id":2562,"word":"fiscal","meaning":"財政的","example":"The student council reviewed its fiscal plan before buying new instruments.","example_zh":"學生會在購買新樂器前，先檢視財務計畫。","original_meaning":"財政的","original_example":"Fiscal policy.","original_example_zh":"財政政策。"},{"source_id":2563,"word":"formidable","meaning":"強大的；艱鉅的","example":"The steep mountain presented a formidable challenge to the hikers.","example_zh":"這座陡峭的山對健行者是個艱鉅的挑戰。","original_meaning":"強大的","original_example":"A formidable opponent.","original_example_zh":"一位強勁的對手。"},{"source_id":2564,"word":"gauge","meaning":"測量","example":"We used a marked stick to gauge the depth of the pond.","example_zh":"我們用有刻度的木棍測量池塘深度。","original_meaning":"測量","original_example":"Gauge the distance.","original_example_zh":"估算距離。"},{"source_id":2565,"word":"glitch","meaning":"故障","example":"A small glitch made the classroom robot stop halfway across the floor.","example_zh":"一個小故障讓教室裡的機器人走到一半就停住了。","original_meaning":"故障","original_example":"A software glitch.","original_example_zh":"軟體故障。"},{"source_id":2566,"word":"grapple","meaning":"搏鬥；努力應付","example":"The rescue team had to grapple with a fallen branch blocking the path.","example_zh":"救援隊必須費力處理擋住道路的倒枝。","original_meaning":"搏鬥","original_example":"Grapple with the issue.","original_example_zh":"努力解決這個問題。"},{"source_id":2567,"word":"hamper","meaning":"妨礙","example":"The heavy mud began to hamper our progress along the trail.","example_zh":"厚重的泥濘開始妨礙我們沿步道前進。","original_meaning":"妨礙","original_example":"Rain hampered the rescue.","original_example_zh":"雨水阻礙了救援工作。"},{"source_id":2568,"word":"herald","meaning":"預示","example":"The first blossoms herald the arrival of spring in our garden.","example_zh":"第一批花朵預告花園裡春天的到來。","original_meaning":"預示","original_example":"Spring heralds new life.","original_example_zh":"春天預示著新生命。"},{"source_id":2569,"word":"hover","meaning":"盤旋","example":"A dragonfly can hover above the pond while searching for insects.","example_zh":"蜻蜓找昆蟲時，能在池塘上方盤旋停留。","original_meaning":"盤旋","original_example":"The helicopter hovered.","original_example_zh":"直升機在空中盤旋。"},{"source_id":2570,"word":"hurdle","meaning":"障礙","example":"The missing tools were a hurdle we had to overcome before building the shelter.","example_zh":"工具不足是我們搭建棚屋前必須克服的障礙。","original_meaning":"障礙","original_example":"Overcome hurdles.","original_example_zh":"克服障礙。"},{"source_id":2571,"word":"imperative","meaning":"必要的","example":"It is imperative to secure the tents before the strong wind arrives.","example_zh":"強風到來前，務必把帳篷固定好。","original_meaning":"必要的","original_example":"It is imperative to act.","original_example_zh":"必須採取行動。"},{"source_id":2572,"word":"impending","meaning":"即將發生的","example":"The dark sky warned us of the impending storm.","example_zh":"陰暗的天空提醒我們暴風雨即將來臨。","original_meaning":"即將發生的","original_example":"Impending danger.","original_example_zh":"迫在眉睫的危險。"},{"source_id":2573,"word":"incidence","meaning":"發生率","example":"The school tracked the incidence of bicycle accidents near the crossing.","example_zh":"學校追蹤路口附近腳踏車事故的發生率。","original_meaning":"發生率","original_example":"The incidence of cancer.","original_example_zh":"癌症的發生率。"},{"source_id":2574,"word":"incite","meaning":"煽動；激起","example":"The captain's speech helped incite enthusiasm for the beach cleanup.","example_zh":"隊長的演說激起大家參加淨灘的熱情。","original_meaning":"煽動","original_example":"Incite violence.","original_example_zh":"煽動暴力。"},{"source_id":2575,"word":"indifferent","meaning":"漠不關心的","example":"While others admired the painting, one visitor seemed indifferent.","example_zh":"大家欣賞畫作時，有位訪客似乎毫不在意。","original_meaning":"漠不關心的","original_example":"He seemed indifferent.","original_example_zh":"他似乎無動於衷。"},{"source_id":2576,"word":"influx","meaning":"湧入","example":"The festival brought an influx of visitors to the small village.","example_zh":"節慶讓大量遊客湧入小村莊。","original_meaning":"湧入","original_example":"An influx of tourists.","original_example_zh":"遊客湧入。"},{"source_id":2577,"word":"inhibit","meaning":"抑制","example":"Too little sunlight can inhibit the growth of young plants.","example_zh":"陽光不足可能抑制幼苗生長。","original_meaning":"抑制","original_example":"Inhibit growth.","original_example_zh":"抑制生長。"},{"source_id":2578,"word":"intermittent","meaning":"間歇的","example":"Intermittent rain forced us to pause our outdoor painting several times.","example_zh":"斷斷續續的雨讓我們戶外寫生時不得不暫停好幾次。","original_meaning":"間歇的","original_example":"Intermittent rain.","original_example_zh":"間歇性降雨。"},{"source_id":2579,"word":"inundate","meaning":"淹沒","example":"Heavy rain can inundate the low fields beside the river.","example_zh":"大雨可能淹沒河邊低窪的田地。","original_meaning":"淹沒","original_example":"Inundated with requests.","original_example_zh":"被請求淹沒。"},{"source_id":2580,"word":"invoke","meaning":"援引","example":"The player tried to invoke the rules when asking for a second attempt.","example_zh":"那名選手請求再試一次時，試著援引比賽規則。","original_meaning":"援引","original_example":"Invoke a law.","original_example_zh":"援引法律。"},{"source_id":2581,"word":"judicial","meaning":"司法的","example":"The students visited a judicial building to learn how courts work.","example_zh":"學生參訪司法大樓，了解法院如何運作。","original_meaning":"司法的","original_example":"The judicial system.","original_example_zh":"司法體系。"},{"source_id":2582,"word":"latent","meaning":"潛在的","example":"The art teacher noticed Mei's latent talent when she shaped her first clay bird.","example_zh":"美第一次捏出陶鳥時，美術老師就發現她潛在的天分。","original_meaning":"潛在的","original_example":"Latent talent.","original_example_zh":"潛在的才華。"},{"source_id":2583,"word":"lethal","meaning":"致命的","example":"The ranger warned that this mushroom contains a lethal poison.","example_zh":"巡山員警告，這種蘑菇含有致命毒素。","original_meaning":"致命的","original_example":"A lethal weapon.","original_example_zh":"致命武器。"},{"source_id":2584,"word":"leverage","meaning":"槓桿","example":"The long handle gave us enough leverage to lift the heavy stone.","example_zh":"長柄提供足夠的槓桿作用，讓我們抬起重石。","original_meaning":"槓桿","original_example":"Financial leverage.","original_example_zh":"財務槓桿。"},{"source_id":2585,"word":"liable","meaning":"有責任的","example":"Anyone who borrows a camera is liable for damage caused by careless handling.","example_zh":"借相機的人必須為粗心操作造成的損壞負責。","original_meaning":"有責任的","original_example":"Liable for damages.","original_example_zh":"須承擔損害賠償責任。"},{"source_id":2586,"word":"logistics","meaning":"後勤","example":"The volunteers planned the logistics of moving food to the shelter.","example_zh":"志工規劃把食物運送到收容所的後勤工作。","original_meaning":"後勤","original_example":"Supply chain logistics.","original_example_zh":"供應鏈物流。"},{"source_id":2587,"word":"lucrative","meaning":"有利可圖的","example":"Selling handmade bowls became a lucrative activity for the school craft fair.","example_zh":"販售手工陶碗成為校園手作市集裡獲利豐厚的活動。","original_meaning":"有利可圖的","original_example":"A lucrative deal.","original_example_zh":"一筆有利可圖的交易。"},{"source_id":2588,"word":"malfunction","meaning":"故障","example":"A loose wire caused the model train to malfunction.","example_zh":"鬆脫的電線使模型火車故障。","original_meaning":"故障","original_example":"A system malfunction.","original_example_zh":"系統故障。"},{"source_id":2589,"word":"mandate","meaning":"命令；規定","example":"The school's safety mandate requires a helmet during cycling activities.","example_zh":"學校的安全規定要求騎車活動時戴安全帽。","original_meaning":"命令","original_example":"A government mandate.","original_example_zh":"政府命令。"},{"source_id":2590,"word":"manifest","meaning":"顯示","example":"The students' excitement began to manifest itself in smiles and eager questions.","example_zh":"學生的興奮開始從笑容與踴躍提問中表現出來。","original_meaning":"顯示","original_example":"Manifest your dreams.","original_example_zh":"實現你的夢想。"},{"source_id":2591,"word":"mediate","meaning":"調解","example":"The counselor helped mediate a disagreement between the two classmates.","example_zh":"輔導老師幫忙調解兩名同學之間的爭執。","original_meaning":"調解","original_example":"Mediate a dispute.","original_example_zh":"調解糾紛。"},{"source_id":2592,"word":"meticulous","meaning":"一絲不苟的","example":"Her meticulous measurements helped the model bridge fit together perfectly.","example_zh":"她一絲不苟的丈量，讓模型橋的零件完美接合。","original_meaning":"一絲不苟的","original_example":"Meticulous work.","original_example_zh":"細緻的工作。"},{"source_id":2593,"word":"milestone","meaning":"里程碑","example":"Finishing the first working robot was a milestone for our science club.","example_zh":"完成第一台能運作的機器人，是科學社的一大里程碑。","original_meaning":"里程碑","original_example":"A major milestone.","original_example_zh":"一個重要的里程碑。"},{"source_id":2594,"word":"mitigate","meaning":"減輕","example":"Planting trees can help mitigate the heat around the playground.","example_zh":"種樹有助於減輕操場周圍的炎熱。","original_meaning":"減輕","original_example":"Mitigate the damage.","original_example_zh":"減輕損害。"},{"source_id":2595,"word":"momentum","meaning":"動力；動量","example":"The cart gained momentum as it rolled down the gentle slope.","example_zh":"推車沿緩坡滑下時，動量逐漸增加。","original_meaning":"動力","original_example":"Gain momentum.","original_example_zh":"積聚動能。"},{"source_id":2596,"word":"monopoly","meaning":"壟斷","example":"One supplier had a monopoly on selling water at the remote campsite.","example_zh":"偏遠營地的飲用水由一家供應商壟斷販售。","original_meaning":"壟斷","original_example":"A market monopoly.","original_example_zh":"市場壟斷。"},{"source_id":2597,"word":"mundane","meaning":"平凡的","example":"Even the mundane task of washing pots can be enjoyable with friends.","example_zh":"即使是洗鍋子這種平凡工作，和朋友一起做也能很愉快。","original_meaning":"平凡的","original_example":"Mundane tasks.","original_example_zh":"瑣碎的日常工作。"},{"source_id":2598,"word":"niche","meaning":"利基","example":"The small shop found a niche by repairing old musical instruments.","example_zh":"這間小店靠修理老樂器找到專門市場。","original_meaning":"利基","original_example":"A market niche.","original_example_zh":"市場利基。"},{"source_id":2599,"word":"nuance","meaning":"細微差別","example":"The painter showed us the nuance between two similar shades of blue.","example_zh":"畫家讓我們看見兩種相似藍色之間的細微差異。","original_meaning":"細微差別","original_example":"Cultural nuances.","original_example_zh":"文化上的細微差異。"},{"source_id":2600,"word":"obsolete","meaning":"過時的","example":"The museum displayed an obsolete camera beside a modern digital one.","example_zh":"博物館把一台過時的相機放在現代數位相機旁展示。","original_meaning":"過時的","original_example":"Obsolete technology.","original_example_zh":"過時的技術。"},{"source_id":2601,"word":"optimal","meaning":"最佳的","example":"We moved the seedlings to a sunny window for optimal growth.","example_zh":"為了讓幼苗長得最好，我們把它們移到陽光充足的窗邊。","original_meaning":"最佳的","original_example":"The optimal solution.","original_example_zh":"最佳解。"},{"source_id":2602,"word":"oversee","meaning":"監督","example":"The teacher will oversee the students as they assemble the greenhouse.","example_zh":"學生組裝溫室時，老師會在旁監督。","original_meaning":"監督","original_example":"Oversee the project.","original_example_zh":"監督該專案。"},{"source_id":2603,"word":"paradox","meaning":"矛盾","example":"It seemed a paradox that the empty room made him feel crowded with memories.","example_zh":"空房間竟讓他覺得回憶擁擠，似乎是個矛盾。","original_meaning":"矛盾","original_example":"A strange paradox.","original_example_zh":"一個奇怪的悖論。"},{"source_id":2604,"word":"paramount","meaning":"至高的","example":"Safety is paramount when we work with sharp tools.","example_zh":"使用鋒利工具時，安全最重要。","original_meaning":"至高的","original_example":"Of paramount importance.","original_example_zh":"至關重要。"},{"source_id":2605,"word":"pave","meaning":"鋪路","example":"The workers will pave the muddy path to make it easier to walk on.","example_zh":"工人將鋪設泥濘小徑，讓行走更方便。","original_meaning":"鋪路","original_example":"Pave the way.","original_example_zh":"鋪平道路。"},{"source_id":2606,"word":"peculiar","meaning":"奇特的","example":"We noticed a peculiar tree with branches that twisted into loops.","example_zh":"我們注意到一棵枝條扭成圈的奇特樹木。","original_meaning":"奇特的","original_example":"A peculiar smell.","original_example_zh":"一股怪味。"},{"source_id":2607,"word":"peer","meaning":"同儕","example":"A supportive peer helped Nora practice her speech after class.","example_zh":"一位支持她的同儕在課後幫諾拉練習演講。","original_meaning":"同儕","original_example":"Peer pressure.","original_example_zh":"同儕壓力。"},{"source_id":2608,"word":"penetrate","meaning":"穿透","example":"A narrow beam of sunlight began to penetrate the dense forest canopy.","example_zh":"一束細細的陽光開始穿透濃密的森林樹冠。","original_meaning":"穿透","original_example":"Penetrate the market.","original_example_zh":"打入市場。"},{"source_id":2609,"word":"perpetuate","meaning":"延續","example":"Sharing the old weaving skills helps perpetuate the village's craft tradition.","example_zh":"分享古老的編織技術，有助於延續村落的工藝傳統。","original_meaning":"延續","original_example":"Perpetuate a myth.","original_example_zh":"延續一個迷思。"},{"source_id":2610,"word":"petition","meaning":"請願","example":"The students prepared a petition asking for a safer crossing near the school.","example_zh":"學生準備請願書，要求改善學校附近的過街安全。","original_meaning":"請願","original_example":"Sign a petition.","original_example_zh":"簽署請願書。"},{"source_id":2611,"word":"pivotal","meaning":"關鍵的","example":"Finding the missing wheel was pivotal to completing our model car.","example_zh":"找到遺失的輪子，是完成模型車的關鍵。","original_meaning":"關鍵的","original_example":"A pivotal moment.","original_example_zh":"關鍵時刻。"},{"source_id":2612,"word":"plausible","meaning":"合理的","example":"The wet footprints offered a plausible explanation for the puddle in the hall.","example_zh":"濕腳印為走廊上的水窪提供了合理的解釋。","original_meaning":"合理的","original_example":"A plausible explanation.","original_example_zh":"一個合理的解釋。"},{"source_id":2613,"word":"plunge","meaning":"猛跌；驟降","example":"The temperature can plunge after sunset in the mountains.","example_zh":"山區日落後，氣溫可能驟降。","original_meaning":"猛跌","original_example":"Stock prices plunged.","original_example_zh":"股價重挫。"},{"source_id":2614,"word":"precaution","meaning":"預防措施","example":"As a precaution, we packed an extra flashlight for the hike.","example_zh":"為了預防萬一，我們健行時多帶了一支手電筒。","original_meaning":"預防措施","original_example":"Take precautions.","original_example_zh":"採取預防措施。"},{"source_id":2615,"word":"precede","meaning":"先於","example":"Dark clouds often precede a heavy rainstorm.","example_zh":"大雨來臨前，往往先出現烏雲。","original_meaning":"先於","original_example":"The event preceded the war.","original_example_zh":"該事件發生在戰爭之前。"},{"source_id":2616,"word":"predicament","meaning":"困境","example":"A broken paddle left the canoe team in a difficult predicament.","example_zh":"槳斷了，讓獨木舟隊陷入困境。","original_meaning":"困境","original_example":"A difficult predicament.","original_example_zh":"艱難的處境。"},{"source_id":2617,"word":"preliminary","meaning":"初步的","example":"We made a preliminary sketch before building the birdhouse.","example_zh":"製作鳥屋前，我們先畫了初步草圖。","original_meaning":"初步的","original_example":"Preliminary results.","original_example_zh":"初步結果。"},{"source_id":2618,"word":"premise","meaning":"前提","example":"The experiment was based on the premise that both plants received equal water.","example_zh":"這個實驗的前提是兩株植物得到相同水量。","original_meaning":"前提","original_example":"A false premise.","original_example_zh":"錯誤的前提。"},{"source_id":2619,"word":"prevalent","meaning":"流行的","example":"Reusable bottles have become prevalent among students at our school.","example_zh":"可重複使用的水壺在我們學校的學生之間已相當普遍。","original_meaning":"流行的","original_example":"A prevalent disease.","original_example_zh":"一種常見的疾病。"},{"source_id":2620,"word":"proclaim","meaning":"宣告","example":"The captain stepped forward to proclaim the start of the sailing race.","example_zh":"隊長上前宣布帆船賽開始。","original_meaning":"宣告","original_example":"Proclaim independence.","original_example_zh":"宣告獨立。"},{"source_id":2621,"word":"prolong","meaning":"延長","example":"Keeping the flowers in cool water can prolong their freshness.","example_zh":"把花放在涼水中能延長保鮮時間。","original_meaning":"延長","original_example":"Prolong the meeting.","original_example_zh":"延長會議時間。"},{"source_id":2622,"word":"prominent","meaning":"突出的","example":"The red lighthouse is a prominent feature of the harbor.","example_zh":"紅色燈塔是港口醒目的特色。","original_meaning":"突出的","original_example":"A prominent figure.","original_example_zh":"知名人物。"},{"source_id":2623,"word":"propel","meaning":"推進","example":"The spinning propeller will propel the model boat across the pond.","example_zh":"旋轉的螺旋槳會推動模型船穿過池面。","original_meaning":"推進","original_example":"Propel the rocket.","original_example_zh":"推動火箭。"},{"source_id":2624,"word":"prosecute","meaning":"起訴","example":"The authorities decided to prosecute the person accused of stealing rare paintings.","example_zh":"當局決定起訴涉嫌偷竊珍貴畫作的人。","original_meaning":"起訴","original_example":"Prosecute the criminal.","original_example_zh":"起訴罪犯。"},{"source_id":2625,"word":"provoke","meaning":"挑釁；激怒","example":"Do not provoke the wild animal by moving too close to it.","example_zh":"別靠野生動物太近，以免激怒牠。","original_meaning":"挑釁","original_example":"Do not provoke him.","original_example_zh":"不要激怒他。"},{"source_id":2626,"word":"proximity","meaning":"接近","example":"The campsite's proximity to the lake made it easy to collect water.","example_zh":"營地靠近湖泊，因此取水很方便。","original_meaning":"接近","original_example":"In close proximity.","original_example_zh":"近在咫尺。"},{"source_id":2627,"word":"prudent","meaning":"謹慎的","example":"It was prudent to check the weather before beginning the hike.","example_zh":"健行出發前先查看天氣，是謹慎的做法。","original_meaning":"謹慎的","original_example":"A prudent decision.","original_example_zh":"一個審慎的決定。"},{"source_id":2628,"word":"radical","meaning":"激進的；徹底的","example":"The club proposed a radical change from disposable cups to reusable ones.","example_zh":"社團提議徹底改變，把拋棄式杯子換成可重複使用的杯子。","original_meaning":"激進的","original_example":"A radical change.","original_example_zh":"根本性的改變。"},{"source_id":2629,"word":"ratify","meaning":"批准","example":"The club members voted to ratify the agreement with the neighboring school.","example_zh":"社團成員投票批准與鄰校的協議。","original_meaning":"批准","original_example":"Ratify the treaty.","original_example_zh":"批准該條約。"},{"source_id":2630,"word":"realm","meaning":"領域","example":"The microscope opened a new realm of tiny living things for the students.","example_zh":"顯微鏡為學生打開了微小生物的新領域。","original_meaning":"領域","original_example":"The realm of science.","original_example_zh":"科學領域。"},{"source_id":2631,"word":"reconcile","meaning":"和解","example":"The classmates decided to reconcile and finish the project together.","example_zh":"同學決定和解，一起完成專題。","original_meaning":"和解","original_example":"Reconcile differences.","original_example_zh":"化解分歧。"},{"source_id":2632,"word":"rectify","meaning":"糾正","example":"We moved the misplaced beam to rectify the error in the bridge model.","example_zh":"我們移動放錯位置的橫梁，修正橋梁模型的錯誤。","original_meaning":"糾正","original_example":"Rectify the mistake.","original_example_zh":"糾正錯誤。"},{"source_id":2633,"word":"redundant","meaning":"多餘的","example":"The extra support was redundant because the shelf was already stable.","example_zh":"架子已經很穩，所以多加的支撐是多餘的。","original_meaning":"多餘的","original_example":"Redundant information.","original_example_zh":"多餘的資訊。"},{"source_id":2634,"word":"refine","meaning":"精煉；改進","example":"The pottery students continued to refine the shape of the bowl.","example_zh":"陶藝學生持續修整陶碗的形狀，使它更細緻。","original_meaning":"精煉","original_example":"Refine the process.","original_example_zh":"優化流程。"},{"source_id":2635,"word":"reinforce","meaning":"加強","example":"We added wooden braces to reinforce the greenhouse frame.","example_zh":"我們加上木支架，強化溫室骨架。","original_meaning":"加強","original_example":"Reinforce the wall.","original_example_zh":"加固牆壁。"},{"source_id":2636,"word":"relentless","meaning":"無情的；持續不斷的","example":"The relentless rain kept the hikers inside the shelter all afternoon.","example_zh":"不停歇的大雨讓健行者整個下午都待在避雨處。","original_meaning":"無情的","original_example":"Relentless rain.","original_example_zh":"連綿不絕的雨。"},{"source_id":2637,"word":"relinquish","meaning":"放棄","example":"The graduating captain will relinquish her role to a younger teammate.","example_zh":"即將畢業的隊長會把職務交給學妹。","original_meaning":"放棄","original_example":"Relinquish control.","original_example_zh":"放棄控制權。"},{"source_id":2638,"word":"render","meaning":"使成為","example":"The broken wheel could render the cart unusable.","example_zh":"壞掉的輪子可能讓推車無法使用。","original_meaning":"使成為","original_example":"Render useless.","original_example_zh":"使之失效。"},{"source_id":2639,"word":"replicate","meaning":"複製","example":"The science club tried to replicate the experiment with a second model.","example_zh":"科學社試著用第二個模型重現實驗。","original_meaning":"複製","original_example":"Replicate the experiment.","original_example_zh":"重現實驗。"},{"source_id":2640,"word":"resent","meaning":"怨恨","example":"Nora began to resent doing all the cleaning while her teammates rested.","example_zh":"隊友都在休息，諾拉卻獨自打掃，因此開始感到不滿。","original_meaning":"怨恨","original_example":"She resented the decision.","original_example_zh":"她對這個決定心懷不滿。"},{"source_id":2641,"word":"restrain","meaning":"抑制；約束","example":"The handler used a leash to restrain the excited dog near the road.","example_zh":"飼主用牽繩控制路邊興奮的小狗。","original_meaning":"抑制","original_example":"Restrain your anger.","original_example_zh":"克制怒氣。"},{"source_id":2642,"word":"retrieve","meaning":"取回","example":"We used a long net to retrieve the ball from the pond.","example_zh":"我們用長柄網把球從池塘裡撈回來。","original_meaning":"取回","original_example":"Retrieve the data.","original_example_zh":"檢索資料。"},{"source_id":2643,"word":"revive","meaning":"復甦","example":"A little water helped revive the wilted plant.","example_zh":"澆一點水讓枯萎的植物恢復生氣。","original_meaning":"復甦","original_example":"Revive the economy.","original_example_zh":"振興經濟。"},{"source_id":2644,"word":"robust","meaning":"強健的；堅固的","example":"The robust wooden bridge safely supported the students crossing the stream.","example_zh":"堅固的木橋安全地承受住過溪學生的重量。","original_meaning":"強健的","original_example":"A robust economy.","original_example_zh":"強勁的經濟。"},{"source_id":2645,"word":"sanction","meaning":"制裁；處分","example":"The school's sanction barred the team from using the gym for a week.","example_zh":"學校的處分禁止該隊使用體育館一週。","original_meaning":"制裁","original_example":"Economic sanctions.","original_example_zh":"經濟制裁。"},{"source_id":2646,"word":"scarcity","meaning":"稀缺","example":"The scarcity of clean water made every full bottle valuable.","example_zh":"乾淨飲水稀缺，讓每一瓶裝滿的水都很珍貴。","original_meaning":"稀缺","original_example":"Water scarcity.","original_example_zh":"水資源短缺。"},{"source_id":2647,"word":"scrutiny","meaning":"審查","example":"The engineer placed the damaged beam under close scrutiny.","example_zh":"工程師仔細檢查受損的橫梁。","original_meaning":"審查","original_example":"Under scrutiny.","original_example_zh":"受到審查。"},{"source_id":2648,"word":"setback","meaning":"挫折","example":"A broken motor was a setback, but the team continued working.","example_zh":"馬達壞掉讓進度受挫，但小組仍繼續努力。","original_meaning":"挫折","original_example":"A major setback.","original_example_zh":"重大挫折。"},{"source_id":2649,"word":"sheer","meaning":"純粹的","example":"The sheer beauty of the waterfall left us speechless.","example_zh":"瀑布純粹的美讓我們說不出話。","original_meaning":"純粹的","original_example":"Sheer determination.","original_example_zh":"堅定的決心。"},{"source_id":2650,"word":"skepticism","meaning":"懷疑論","example":"The students showed skepticism until they tested the surprising claim themselves.","example_zh":"學生原本抱持懷疑，直到親自測試那個驚人的說法。","original_meaning":"懷疑論","original_example":"Healthy skepticism.","original_example_zh":"健康的懷疑態度。"},{"source_id":2651,"word":"sparse","meaning":"稀疏的","example":"Only sparse vegetation grew on the dry hillside.","example_zh":"乾燥山坡上只長著稀疏的植物。","original_meaning":"稀疏的","original_example":"Sparse vegetation.","original_example_zh":"稀疏的植被。"},{"source_id":2652,"word":"speculate","meaning":"推測","example":"We could only speculate about which animal had left the muddy tracks.","example_zh":"我們只能推測是哪種動物留下那些泥腳印。","original_meaning":"推測","original_example":"We can only speculate.","original_example_zh":"我們只能推測。"},{"source_id":2653,"word":"spontaneous","meaning":"自發的","example":"A spontaneous round of applause followed the student's brave performance.","example_zh":"學生勇敢表演後，觀眾自發地鼓起掌來。","original_meaning":"自發的","original_example":"A spontaneous reaction.","original_example_zh":"自發性反應。"},{"source_id":2654,"word":"stagnant","meaning":"停滯的","example":"The stagnant water in the unused pond had become cloudy.","example_zh":"廢棄池塘裡停滯不流的水已變得混濁。","original_meaning":"停滯的","original_example":"A stagnant economy.","original_example_zh":"停滯的經濟。"},{"source_id":2655,"word":"stark","meaning":"嚴峻的","example":"The empty reservoir was a stark reminder of the long drought.","example_zh":"空蕩蕩的水庫嚴峻地提醒大家乾旱已持續很久。","original_meaning":"嚴峻的","original_example":"A stark contrast.","original_example_zh":"鮮明對比。"},{"source_id":2656,"word":"stereotype","meaning":"刻板印象","example":"The club challenged the stereotype that only boys enjoy building robots.","example_zh":"社團打破只有男生喜歡製作機器人的刻板印象。","original_meaning":"刻板印象","original_example":"Break stereotypes.","original_example_zh":"打破刻板印象。"},{"source_id":2657,"word":"strategic","meaning":"策略的","example":"The team placed the water station in a strategic spot beside the main trail.","example_zh":"小組把飲水站設在主要步道旁的重要位置。","original_meaning":"策略的","original_example":"A strategic plan.","original_example_zh":"一項戰略計畫。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-exert-01-v1","level":"senior","word":"exert","sort_order":1,"sense":"施加","alt_zh":"幾名高中生一起穩定施力，把裝滿園藝用品的推車推上緩坡。","example":"The students had to exert steady pressure to move the heavy cart.","example_zh":"學生必須持續施力，才能推動沉重的推車。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/exert-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-expedition-01-v1","level":"senior","word":"expedition","sort_order":1,"sense":"遠征；考察","alt_zh":"老師帶高中生背著背包、拿植物觀察冊走入山林。","example":"Our class joined an expedition to study plants in the mountain forest.","example_zh":"我們班參加考察隊，研究山林裡的植物。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/expedition-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fallacy-01-v1","level":"senior","word":"fallacy","sort_order":1,"sense":"謬誤","alt_zh":"老師從相同高度放開兩顆大小相近的金屬球，高中生用攝影機觀察落地。","example":"The teacher exposed the fallacy that heavier objects always fall faster.","example_zh":"老師指出較重的物體總是落得較快這種謬誤。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fallacy-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-famine-01-v1","level":"senior","word":"famine","sort_order":1,"sense":"饑荒","alt_zh":"救援人員在乾旱村落，把米袋交給缺糧家庭，氣氛關懷而有尊嚴。","example":"Relief workers delivered grain to families affected by the famine.","example_zh":"救援人員把穀物送到受饑荒影響的家庭。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/famine-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fiscal-01-v1","level":"senior","word":"fiscal","sort_order":1,"sense":"財政的","alt_zh":"高中學生會在桌上分配裝硬幣的透明罐，旁邊有待購樂器模型。","example":"The student council reviewed its fiscal plan before buying new instruments.","example_zh":"學生會在購買新樂器前，先檢視財務計畫。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fiscal-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-formidable-01-v1","level":"senior","word":"formidable","sort_order":1,"sense":"強大的；艱鉅的","alt_zh":"高中健行隊在安全山腳仰望高聳陡峭的山峰，認真準備裝備。","example":"The steep mountain presented a formidable challenge to the hikers.","example_zh":"這座陡峭的山對健行者是個艱鉅的挑戰。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/formidable-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-gauge-01-v1","level":"senior","word":"gauge","sort_order":1,"sense":"測量","alt_zh":"高中生在老師看護下從岸邊垂直放入只有刻線的測深木棍。","example":"We used a marked stick to gauge the depth of the pond.","example_zh":"我們用有刻度的木棍測量池塘深度。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/gauge-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-glitch-01-v1","level":"senior","word":"glitch","sort_order":1,"sense":"故障","alt_zh":"高中生蹲下查看教室地板上突然停住的輪式機器人。","example":"A small glitch made the classroom robot stop halfway across the floor.","example_zh":"一個小故障讓教室裡的機器人走到一半就停住了。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/glitch-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-grapple-01-v1","level":"senior","word":"grapple","sort_order":1,"sense":"搏鬥；努力應付","alt_zh":"成年救援隊員戴手套，合力搬開擋住步道的粗大倒枝。","example":"The rescue team had to grapple with a fallen branch blocking the path.","example_zh":"救援隊必須費力處理擋住道路的倒枝。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/grapple-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-hamper-01-v1","level":"senior","word":"hamper","sort_order":1,"sense":"妨礙","alt_zh":"高中健行者的鞋陷在厚泥中，步行吃力，同伴在旁協助。","example":"The heavy mud began to hamper our progress along the trail.","example_zh":"厚重的泥濘開始妨礙我們沿步道前進。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/hamper-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-herald-01-v1","level":"senior","word":"herald","sort_order":1,"sense":"預示","alt_zh":"高中生在尚有殘雪的花園中發現枝頭第一批春花。","example":"The first blossoms herald the arrival of spring in our garden.","example_zh":"第一批花朵預告花園裡春天的到來。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/herald-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-hover-01-v1","level":"senior","word":"hover","sort_order":1,"sense":"盤旋","alt_zh":"高中生觀察池塘上方振翅懸停的蜻蜓。","example":"A dragonfly can hover above the pond while searching for insects.","example_zh":"蜻蜓找昆蟲時，能在池塘上方盤旋停留。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/hover-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-hurdle-01-v1","level":"senior","word":"hurdle","sort_order":1,"sense":"障礙","alt_zh":"高中生面對只有少數工具的工具箱與未完成棚架，合作尋找解決辦法。","example":"The missing tools were a hurdle we had to overcome before building the shelter.","example_zh":"工具不足是我們搭建棚屋前必須克服的障礙。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/hurdle-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-imperative-01-v1","level":"senior","word":"imperative","sort_order":1,"sense":"必要的","alt_zh":"老師指導高中生把營繩拉緊、營釘固定，天空烏雲漸近。","example":"It is imperative to secure the tents b