ations/senior/paradox-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-paramount-01-v1","level":"senior","word":"paramount","sort_order":1,"sense":"至高的","alt_zh":"老師先確認高中生戴好護目鏡與手套，才示範安全使用工具。","example":"Safety is paramount when we work with sharp tools.","example_zh":"使用鋒利工具時，安全最重要。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/paramount-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-pave-01-v1","level":"senior","word":"pave","sort_order":1,"sense":"鋪路","alt_zh":"成年工人在泥地小徑上仔細鋪設平整石磚，高中生從安全區觀看。","example":"The workers will pave the muddy path to make it easier to walk on.","example_zh":"工人將鋪設泥濘小徑，讓行走更方便。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/pave-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-peculiar-01-v1","level":"senior","word":"peculiar","sort_order":1,"sense":"奇特的","alt_zh":"高中健行者驚訝地觀察樹枝自然盤繞成圈的老樹。","example":"We noticed a peculiar tree with branches that twisted into loops.","example_zh":"我們注意到一棵枝條扭成圈的奇特樹木。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/peculiar-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-peer-01-v1","level":"senior","word":"peer","sort_order":1,"sense":"同儕","alt_zh":"兩名高中同學在教室裡，一人練習演講，另一人專注聆聽並鼓勵。","example":"A supportive peer helped Nora practice her speech after class.","example_zh":"一位支持她的同儕在課後幫諾拉練習演講。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/peer-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-penetrate-01-v1","level":"senior","word":"penetrate","sort_order":1,"sense":"穿透","alt_zh":"森林中一道明亮陽光穿過濃密樹葉，照在高中健行者前的地面。","example":"A narrow beam of sunlight began to penetrate the dense forest canopy.","example_zh":"一